if [[ -z "${INPUT//[[:space:]]/}" ]]; then
    echo "self-learn lrn-a43bf00c: empty hook input — failing closed" >&2
    exit 2
fi
TOOL=$(jq -r '.tool_name // empty' <<<"$INPUT")

case "$TOOL" in
    Bash)
        VALUE=$(jq -r '.tool_input.command // empty' <<<"$INPUT")
