grep -qE -- '(bws[[:space:]]+secret[[:space:]]+list|bw[[:space:]]+list[[:space:]]+items)[^|]*\|[^|]*(awk|sed|grep)' <<<"" || PROBE_RC=$?
if [[ "$PROBE_RC" -ge 2 ]]; then
    echo "self-learn lrn-a43bf00c: guard regex is invalid — failing closed" >&2
    exit 2
fi

MATCH_RC=0
grep -qE -- '(bws[[:space:]]+secret[[:space:]]+list|bw[[:space:]]+list[[:space:]]+items)[^|]*\|[^|]*(awk|sed|grep)' <<<"$VALUE" || MATCH_RC=$?
